@app.route('/predict', methods=['POST'])
def predict():
    # 从请求中获取输入数据
    data = request.get_json(force=True)
    # 将输入数据转换为适合模型的格式
    current_data = data['values']

    global input_data
    # 检查数据的类型
    if not isinstance(input_data, deque):
        # 如果数据不是deque，将其从tensor转换为deque
        input_data.reshape(300,2)
        list_data = input_data.tolist()
        input_data = deque(list_data, maxlen=300)
    input_data.append(current_data)
    input_data = np.array(input_data)
    input_data = torch.tensor(input_data, dtype=torch.float32)
    input_data.reshape(-1,300,2)
    print(input_data)
    

    # 使用模型进行预测
    criterion = nn.L1Loss(reduction='sum').to(config.device)
    with torch.no_grad():
        seq_pred = model(input_data)
        loss = criterion(seq_pred, input_data)

    THRESHOLD = 10.0
    if loss <= THRESHOLD:
        return jsonify(True)
    else:
        print(loss)
        return jsonify(False)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000, debug=True)
